SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='roommate_interests' AND COLUMN_NAME='message');
SET @sql = IF(@c=0, 'ALTER TABLE roommate_interests ADD COLUMN message VARCHAR(1000) NULL AFTER phone', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
